from collections import Counter
class Solution:
    def mostFrequentEven(self, nums: List[int]) -> int:
        c = Counter(x for x in nums if x % 2 == 0)
        if not c:
            return -1
        m = max(c.values())
        return min(k for k in c if c[k] == m)

