class Solution {
public:
    int mostFrequentEven(vector<int>& nums) {
        unordered_map<int,int> c;
        for (int x : nums) if (x % 2 == 0) c[x]++;
        int best = -1, bc = 0;
        for (auto& [k, v] : c)
            if (v > bc || (v == bc && k < best)) { bc = v; best = k; }
        return best;
    }
};

