class Solution:
    def mostFrequentEven(self, nums: List[int]) -> int:
        ev = sorted(x for x in nums if x % 2 == 0)
        if not ev:
            return -1
        best, bc, cur, cc = ev[0], 0, None, 0
        for x in ev + [None]:
            if x == cur:
                cc += 1
            else:
                if cc > bc:
                    bc, best = cc, cur
                cur, cc = x, 1
        return best

