class Solution {
public:
    int mostFrequentEven(vector<int>& nums) {
        vector<int> ev;
        for (int x : nums) if (x % 2 == 0) ev.push_back(x);
        if (ev.empty()) return -1;
        sort(ev.begin(), ev.end());
        int best = ev[0], bc = 0, cur = ev[0], cc = 0;
        for (int x : ev) {
            if (x == cur) cc++;
            else { if (cc > bc) { bc = cc; best = cur; } cur = x; cc = 1; }
        }
        if (cc > bc) best = cur;
        return best;
    }
};

