var mostFrequentEven = function(nums) {
    const ev = nums.filter(x => x % 2 === 0).sort((a, b) => a - b);
    if (!ev.length) return -1;
    let best = ev[0], bc = 0, cur = null, cc = 0;
    for (const x of ev) {
        if (x === cur) cc++;
        else { if (cc > bc) { bc = cc; best = cur; } cur = x; cc = 1; }
    }
    if (cc > bc) best = cur;
    return best;
};
